\begin{prop}
\label{lknadlnad}
For $X=P\backslash G=M\backslash K$, the parabolic tangent groupoid $\mathbb{T}_HX$ is set theoretically given by
$$\mathbb{T}_HX=V\times_M K\times \{0\}\dot{\bigcup} M\backslash K\times M\backslash K\times A\rightrightarrows M\backslash K \times \overline{A}.$$
It is endowed with a smooth structure, defined by declaring $M\backslash K\times M\backslash K\times A\subseteq \mathbb{T}_HX$ to be an open submanifold and declaring the following map a smooth embedding 
$$\psi:V\times_M K\times \overline{A}\to \mathbb{T}_HX, 
\quad 
(M(k,v),a)\mapsto\begin{cases}
(Mk\kappa(ava^{-1})^{-1},Mk,a)\; &a\in A,\\
{}\\
(M(v,k),0),\; &a=0.
\end{cases}$$
\end{prop}

\begin{lemma}\label{eta_lemma}

	Suppose $\mathrm{char}(\BF_q) = p$, factor $q - 1 = \ell \cdot m$ where $\ell$ is an odd prime with $\ell \nmid m$. Set $o_1 = o_1(x, y) = \frac{q - 1}{\gcd\pt{\log_\varepsilon(x/y), q - 1}}$ where $x, y \in \BF_q^\times$ and $o_2 = o_2(z) = \frac{\log_\omega(z)}{\gcd\pt{\log_\omega(z), q + 1}}$ where $z \in \BK_q^\times$. Then we have
	\[\eta(g) = \left\{\begin{aligned}
		&(q + 1)\cdot\one\fk{{\mu_{m}(x)}},&&\text{ if } g = c_1(x);\\
		&\pt{{q}{p^{-1}} + 1}\cdot\one\fk{{\mu_{m}(x)}}, &&\text{ if } g = c_2(x);\\
		&\one\fk{\mu_m(x)} + \one\fk{\mu_m(y)} + \gcd{(\log_\varepsilon\pt{{x}/{y}}, q - 1)}\cdot\one\fk{\mu_{m}(x^{o_1})},&&\text{ if } g = c_3(x, y);\\
		&\gcd(\log_\omega(z), q + 1)\cdot\one\fk{\mu_{m}\pt{\varepsilon^{o_2}}},&&\text{ if } g = c_4(z).
	\end{aligned}\right.\]	

\end{lemma}

\begin{prop}\label{prop:equiv3}
There is an equivalence between the category $\mod_Y\!\text{-}\wAm$ of coherent right $\wAm$-modules on $Y$ and the category of $M_Y$-twisted $Q(m)$-quiver sheaves $(\{F_i\}_{i\in \zm}, \{\psi_i\}_{i\in \zm} )$ with the additional condition that for each $i\in \zm$, the composition of arrows around the loop (suppressing the twist by the identity on $\pi^*K_C^{-1}$) yields:
\[\psi_{i-1}\circ \cdots \circ \psi_i = \operatorname{Id}_{F_i}\otimes_{\O_Y} \lambda  \in Hom_{\O_Y}(F_i\otimes_{\O_Y} \pi^*K_C^{-m}, F_i )\]
where the subcript of $\psi_i$ is understood modulo $m$.
\end{prop}

\begin{theo}
\label{compact_para_quant}
The Dirac type operator $D$, defined in equation~\eqref{quant_dirac_op}, subject to the boundary conditions given in
Proposition~{\rm \ref{bndy_cond_quant}}, is a~right invertible operator and is left invertible modulo compact operators.
Moreover $D$ has a~compact parametrix.
\end{theo}
